  "inlineSchema": "// Prisma schema — Sistema de e-commerce (catálogo + pedidos + pago manual BP Link)\n// Arquitectura monolítica modular: React -> Node/Express -> PostgreSQL\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// =========================================================\n// USUARIOS ADMIN\n// =========================================================\nmodel AdminUser {\n  id           String   @id @default(uuid())\n  fullName     String\n  email        String   @unique\n  passwordHash String\n  role         String   @default(\"admin\") // admin | staff (ampliable a futuro)\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n\n  confirmedPayments Payment[]            @relation(\"PaymentConfirmedBy\")\n  statusChanges     OrderStatusHistory[]\n\n  @@map(\"admin_users\")\n}\n\n// =========================================================\n// CATALOGO\n// =========================================================\nmodel Category {\n  id        String    @id @default(uuid())\n  name      String\n  slug      String    @unique\n  isActive  Boolean   @default(true)\n  createdAt DateTime  @default(now())\n  products  Product[]\n\n  @@map(\"categories\")\n}\n\nmodel Product {\n  id          String    @id @default(uuid())\n  name        String\n  description String?\n  price       Decimal   @db.Decimal(10, 2)\n  imageUrl    String?\n  stock       Int       @default(0)\n  isActive    Boolean   @default(true) // nunca borrar físicamente si tiene pedidos asociados\n  categoryId  String?\n  category    Category? @relation(fields: [categoryId], references: [id])\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  cartItems  CartItem[]\n  orderItems OrderItem[]\n\n  @@map(\"products\")\n}\n\n// =========================================================\n// CLIENTE\n// =========================================================\nmodel Customer {\n  id             String   @id @default(uuid())\n  fullName       String\n  primaryPhone   String\n  secondaryPhone String?\n  email          String?\n  address        String?\n  createdAt      DateTime @default(now())\n\n  carts  Cart[]\n  orders Order[]\n\n  @@map(\"customers\")\n}\n\n// =========================================================\n// CARRITO (previo al pedido)\n// =========================================================\nmodel Cart {\n  id         String    @id @default(uuid())\n  customerId String?\n  customer   Customer? @relation(fields: [customerId], references: [id])\n  sessionId  String? // para carritos de invitados antes de identificar al cliente\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  items CartItem[]\n\n  @@map(\"carts\")\n}\n\nmodel CartItem {\n  id        String  @id @default(uuid())\n  cartId    String\n  cart      Cart    @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n  quantity  Int\n\n  @@map(\"cart_items\")\n}\n\n// =========================================================\n// PEDIDO\n// =========================================================\nenum OrderStatus {\n  Pending\n  Completed\n  Rejected\n  PaymentFailed\n}\n\nmodel Order {\n  id          String   @id @default(uuid())\n  orderNumber Int      @default(autoincrement())\n  customerId  String\n  customer    Customer @relation(fields: [customerId], references: [id])\n\n  // Snapshot histórico de datos de contacto (no depender del Customer actual)\n  contactName     String\n  primaryPhone    String\n  secondaryPhone  String?\n  deliveryAddress String\n\n  status OrderStatus @default(Pending)\n\n  subtotal      Decimal @db.Decimal(10, 2)\n  discountTotal Decimal @default(0) @db.Decimal(10, 2)\n  taxTotal      Decimal @default(0) @db.Decimal(10, 2)\n  shippingTotal Decimal @default(0) @db.Decimal(10, 2)\n  total         Decimal @db.Decimal(10, 2)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  items    OrderItem[]\n  payments Payment[]\n\n  statusHistory OrderStatusHistory[]\n\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id        String  @id @default(uuid())\n  orderId   String\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n\n  // Snapshot histórico — no debe cambiar si el producto cambia después\n  productName String\n  unitPrice   Decimal @db.Decimal(10, 2)\n  quantity    Int\n  discount    Decimal @default(0) @db.Decimal(10, 2)\n  tax         Decimal @default(0) @db.Decimal(10, 2)\n  subtotal    Decimal @db.Decimal(10, 2)\n\n  @@map(\"order_items\")\n}\n\n// Historial de cambios de estado del pedido (trazabilidad)\nmodel OrderStatusHistory {\n  id          String       @id @default(uuid())\n  orderId     String\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  fromStatus  OrderStatus?\n  toStatus    OrderStatus\n  changedById String?\n  changedBy   AdminUser?   @relation(fields: [changedById], references: [id])\n  note        String?\n  createdAt   DateTime     @default(now())\n\n  @@map(\"order_status_history\")\n}\n\n// =========================================================\n// PAGO (entidad independiente del pedido)\n// =========================================================\nenum PaymentStatus {\n  Pending\n  Paid\n  Failed\n  Expired\n  Cancelled\n}\n\nmodel Payment {\n  id             String        @id @default(uuid())\n  orderId        String\n  order          Order         @relation(fields: [orderId], references: [id])\n  provider       String        @default(\"BANPAIS\")\n  method         String        @default(\"BP_LINK\")\n  amount         Decimal       @db.Decimal(10, 2)\n  status         PaymentStatus @default(Pending)\n  paymentLink    String?\n  transactionRef String?\n  createdAt      DateTime      @default(now())\n  paidAt         DateTime?\n  confirmedById  String?\n  confirmedBy    AdminUser?    @relation(\"PaymentConfirmedBy\", fields: [confirmedById], references: [id])\n  notes          String?\n\n  @@map(\"payments\")\n}\n",
